content.text:
{
  "name": "TC038烘箱温控器",
  "name_en": "TC038 Oven Temperature Controller",
  "manufacturer": "HCP",
  "description": "用于 HCP TC038 实验室烘箱的温度控制与状态读取，可读取当前温度、设置温度设定值、配置监视寄存器并查询设备信息，适用于烘箱加热过程的温度调节与监测。",
  "description_en": "Temperature control and status interface for the HCP TC038 laboratory oven. It can read the current temperature, set the temperature setpoint, configure monitored registers, and query device information for oven heating control and monitoring.",
  "actions": [
    {
      "action_name": "auto-monitored_quantity",
      "description": "获取/设置监视量",
      "description_en": "get/set monitored quantity"
    },
    {
      "action_name": "auto-query",
      "description": "发送命令并读取控制器响应",
      "description_en": "send a command and read the controller response"
    },
    {
      "action_name": "auto-sendcmd",
      "description": "向烘箱控制器发送命令",
      "description_en": "send a command to the oven controller"
    },
    {
      "action_name": "auto-setpoint",
      "description": "获取/设置温度设定值",
      "description_en": "get/set temperature setpoint"
    },
    {
      "action_name": "auto-temperature",
      "description": "获取当前温度",
      "description_en": "get current temperature"
    },
    {
      "action_name": "auto-monitored_value",
      "description": "获取监视值",
      "description_en": "get monitored value"
    },
    {
      "action_name": "auto-information",
      "description": "获取设备信息",
      "description_en": "get device information"
    }
  ],
  "tag_hints": [
    "laboratory oven",
    "temperature control",
    "temperature setpoint",
    "temperature monitoring",
    "heating control",
    "serial command protocol"
  ]
}

